using Godot;
using System;
using System.Linq;
using System.Threading.Tasks;
public partial class MigrationScene {
 async Task NewThreatChecks(){
  var original=game;var room=dungeon;var position=player.Position;Node3D wall=null;
  try{ClearEnemies();game=new ExpeditionGame(ProjectSettings.GlobalizePath("user://tests/new-threats-"+Guid.NewGuid()+".json")){NoDiskSave=true};game.Shield=0;EnterDungeon(HeartDungeon());ClearEnemies();player.Position=new(0,.1f,0);game.Life.Health=100;
   MigrationChecks.Assert(ExpeditionThreat.All.Length==10&&ExpeditionThreat.All.Select(t=>t.Kind).Distinct().Count()==10,"Ten unique new combat types");
   for(int tier=1;tier<=5;tier++)for(int i=0;i<600;i++){string id="habitat/new-check/"+i;id=ExpeditionThreatEcology.Stamp(id,tier,0,(ThreatHabitat)1023);var kind=ExpeditionCampaign.Kind(id,tier,0);var t=ExpeditionThreat.Find(kind);if(t!=null)MigrationChecks.Assert(tier>=t.Min&&tier<=t.Max&&(!t.NightOnly||tier>=5),"Population respects biome tier and night gates");if(tier==1)MigrationChecks.Assert(t==null,"Starting tier remains peaceful");MigrationChecks.Assert(kind==ExpeditionCampaign.Kind(id,tier,0),"Seeded kind stable across reloads and peers");}
   MigrationChecks.Assert(ExpeditionThreat.All.All(t=>Enumerable.Range(t.Min,t.Max-t.Min+1).Any(tier=>Enumerable.Range(0,3000).Any(i=>ExpeditionCampaign.Kind(ExpeditionThreatEcology.Stamp("night/new-check/"+i,tier,1,(ThreatHabitat)1023),tier,1)==t.Kind))),"Every new type can spawn through real population selection");
   ThreatEcologyChecks();
   Infected Spawn(string kind,float z=-7){ClearEnemies();string id="special/"+kind+"/new-check/"+Guid.NewGuid();AddEnemy(id,0,z,ExpeditionThreat.Find(kind).Min);var e=infected.Single();e.Body.LookAt(new Vector3(0,0,0));return e;}
   foreach(var spec in ExpeditionThreat.All){var e=Spawn(spec.Kind);MigrationChecks.Assert(e.Hp>=spec.Health&&e.Visual.FindChildren("*","MeshInstance3D",true,false).Count>3,"Health and physical model / "+spec.Name);PoseNewThreat(e);}
   var enemy=Spawn("mossback",-10);TickNewThreat(enemy,.1);MigrationChecks.Assert(enemy.BossState=="threat-hidden","Mossback waits in ambush");enemy.Memory=3;TickNewThreat(enemy,.1);MigrationChecks.Assert(enemy.BossState!="threat-hidden","Noise wakes Mossback");
   enemy=Spawn("howler");enemy.BossTime=0;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);TickNewThreat(enemy,.01);MigrationChecks.Assert(enemy.BossState=="howler-windup","Howler warns before screaming");ReactEnemyHit(enemy,true);MigrationChecks.Assert(enemy.BossState=="threat-recover","Attack interrupts howl");enemy.Stagger=0;enemy.BossState="howler-windup";enemy.BossTime=0;AddEnemy("new-check/listener",5,-5,2);var listener=infected.Last();listener.Memory=0;TickNewThreat(enemy,.01);MigrationChecks.Assert(listener.Memory>0,"Howl alerts nearby existing infected");
   enemy=Spawn("bilecaster");enemy.BossState="bilecaster-windup";enemy.BossAim=player.Position;enemy.BossTime=0;TickNewThreat(enemy,.01);MigrationChecks.Assert(millPools.Any(p=>p.Position.DistanceTo(player.Position)<1),"Spitter leaves real target-position acid");ClearMillPools();
   enemy=Spawn("gravecrawler");MigrationChecks.Assert(((CapsuleShape3D)enemy.Body.GetChild<CollisionShape3D>(0).Shape).Height<1.2f,"Crawler has matching low collision");
   enemy=Spawn("roadbreaker");enemy.BossTime=0;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);TickNewThreat(enemy,.01);MigrationChecks.Assert(enemy.BossState=="roadbreaker-windup","Brute charge is telegraphed");enemy.BossTime=0;TickNewThreat(enemy,.01);MigrationChecks.Assert(enemy.BossState=="threat-rush","Brute enters committed rush");enemy.BossTime=0;TickNewThreat(enemy,.01);MigrationChecks.Assert(enemy.BossState=="threat-recover","Charge ends in punishable recovery");
   enemy=Spawn("riot");MigrationChecks.Assert(RiotResistance(enemy)<.5,"Shield resists frontal body hits");enemy.Body.Rotation+=new Vector3(0,Mathf.Pi,0);MigrationChecks.Assert(RiotResistance(enemy)==1,"Flanking bypasses shield");
   enemy=Spawn("wirebound");enemy.BossState="wirebound-windup";enemy.BossAim=player.Position;enemy.BossTime=0;game.Stamina=100;TickNewThreat(enemy,.01);MigrationChecks.Assert(game.Stamina==65,"Wire lash drains stamina without rooting");
   enemy=Spawn("blooddrinker",-1.5f);enemy.Hp=60;enemy.AttackState="windup";enemy.AttackTime=0;enemy.Memory=8;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);double hp=game.Life.Health;TickNewThreat(enemy,.01);MigrationChecks.Assert(game.Life.Health<hp&&enemy.Hp==90,"Blooddrinker heals only after actual melee damage");
   enemy=Spawn("palehunter");enemy.BossTime=0;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);TickNewThreat(enemy,.01);MigrationChecks.Assert(enemy.BossState=="palehunter-windup","Hunter leap is telegraphed");
   enemy=Spawn("cinder");enemy.Hp=0;int food=game.Life.Food;KillEnemy(enemy);KillEnemy(enemy);MigrationChecks.Assert(infected.Contains(enemy)&&enemy.BossState=="cinder-death"&&enemy.BossTime==1.8,"Cinder death warning cannot duplicate or reset");TickNewThreat(enemy,2);MigrationChecks.Assert(!infected.Contains(enemy)&&millPools.Any(p=>p.Kind==1),"Cinder death creates finite burning ground");int materials=game.Craft.Materials[4];game.Kill(enemy.Id,3,0);MigrationChecks.Assert(game.Craft.Materials[4]==materials,"Specialist loot cannot duplicate");ClearMillPools();
   var state=Json.Read<ExpeditionGameSave>(Json.Write(game.Save));MigrationChecks.Assert(state.Profile.Survivor.Defeated.Contains(enemy.Id),"Enemy defeat and rewards persist");
   GD.Print("PASS / ten enemy models/types, deterministic tier/night seeding, ambush, howl interruption/hearing, acid, crawler collision, warned charge, directional shield, stamina lash, healing strike, hunter leap, finite fire/death and saved rewards");
  }finally{ClearEnemies();ClearMillPools();if(wall!=null)wall.QueueFree();game=original;if(dungeon!=null)ExitDungeon(false);dungeon=room;player.Position=position;}
 }
 async void RunNewThreatChecks(){try{await NewThreatChecks();GetTree().Quit();}catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
}
